begin;
-- Extend only Howdy's catalog; existing crew entries, favorites and planning stay intact.
alter table public.howdy_ideas drop constraint howdy_ideas_region_check;
alter table public.howdy_ideas add constraint howdy_ideas_region_check check(region in ('Tennessee','Arkansas','Texas','Louisiana','Andere'));
alter table public.howdy_ideas drop constraint howdy_ideas_photo_key_check;
alter table public.howdy_ideas add constraint howdy_ideas_photo_key_check check(photo_key in ('nashville','memphis','hotsprings','dallas','fortworth','waco','austin','hillcountry','sanantonio','roadtrip','gruene','bandera','houston','galveston','littlerock','neworleans'));
insert into public.howdy_ideas as existing (id,kind,title,location,region,description,url,photo_key)
select id,kind,title,location,region,description,url,photo_key
from jsonb_to_recordset($catalog$[{"id":"destination-nashville","kind":"destination","title":"Nashville","location":"Nashville","region":"Tennessee","description":"Country am Broadway, Ryman oder Country Music Hall of Fame: Als Musikauftakt würden wir zwei bis drei Nächte vorsehen. Für Nashville plus Texas passt eher die 14-Tage-Variante; bei zehn Tagen bleibt mit einer reinen Texas-Route mehr Zeit vor Ort. Shows erst nach Terminprüfung auswählen.","url":"https://www.visitmusiccity.com/","photo_key":"nashville"},{"id":"destination-memphis","kind":"destination","title":"Memphis","location":"Memphis","region":"Tennessee","description":"Beale Street, Sun Studio und Graceland als Auswahl, nicht als Pflichtprogramm. Zwei Nächte geben Platz für Musik und einen entspannten Abend. Passt zwischen Nashville und Arkansas; nicht zusätzlich in eine kurze Texas-Runde quetschen.","url":"https://www.memphistravel.com/","photo_key":"memphis"},{"id":"destination-hotsprings","kind":"destination","title":"Hot Springs","location":"Hot Springs","region":"Arkansas","description":"Bathhouse Row, Nationalpark-Spaziergang und eventuell ein Thermalbad im Badehaus. Eine Nacht als Pause zwischen Memphis und Fort Worth vorschlagen. Der anschließende Transfer nach Texas ist eine längere Fahretappe; Badeangebote und Zeiten vorher prüfen.","url":"https://www.nps.gov/hosp/index.htm","photo_key":"hotsprings"},{"id":"destination-dallas","kind":"destination","title":"Dallas","location":"Dallas","region":"Texas","description":"Downtown, Sixth Floor Museum oder gemeinsam BBQ essen. Als Ausflug von einer gemeinsamen Basis im Raum Dallas/Fort Worth möglich. Für die kompakte Route lieber insgesamt zwei Nächte in der Region als ein zusätzlicher Hotelwechsel.","url":"https://www.visitdallas.com/","photo_key":"dallas"},{"id":"destination-fortworth","kind":"destination","title":"Fort Worth","location":"Fort Worth","region":"Texas","description":"Stockyards, Westernläden und Country-Musik: zwei Nächte als Cowboy-Auftakt in Texas vorschlagen. Dallas lässt sich optional ergänzen. Viehtrieb, Rodeo und Konzerte nach dem tatsächlichen Reisetermin auswählen; Veranstaltungen sind noch nicht gebucht.","url":"https://www.fortworth.com/","photo_key":"fortworth"},{"id":"destination-waco","kind":"destination","title":"Waco","location":"Waco","region":"Texas","description":"Magnolia Market oder Suspension Bridge als Pause auf der Fahrt von Dallas/Fort Worth nach Austin. Für unsere kürzeren Varianten reicht ein halber Tag ohne zusätzlichen Hotelwechsel. Öffnungstage vorab prüfen.","url":"https://www.destinationwaco.org/","photo_key":"waco"},{"id":"destination-austin","kind":"destination","title":"Austin","location":"Austin","region":"Texas","description":"South Congress, Capitol, Foodtrucks und abends Live-Musik. Zwei Nächte als Planungsansatz, bei Musikfokus gern länger. Barton Springs nur bei passenden Bedingungen ergänzen. Von hier lassen sich Gruene oder das Hill Country in die Route einbauen.","url":"https://www.austintexas.org/","photo_key":"austin"},{"id":"destination-hillcountry","kind":"destination","title":"Fredericksburg & Luckenbach","location":"Fredericksburg & Luckenbach","region":"Texas","description":"Zwei Nächte für Fredericksburg, Landstraßen und einen Country-Abstecher nach Luckenbach vorschlagen. Eine gute ruhigere Ergänzung zu Austin und San Antonio. Musiktermine in Luckenbach erst für unsere konkreten Tage prüfen.","url":"https://www.visitfredericksburgtx.com/","photo_key":"hillcountry"},{"id":"destination-sanantonio","kind":"destination","title":"San Antonio","location":"San Antonio","region":"Texas","description":"River Walk, Alamo und Tex-Mex: zwei bis drei Nächte als entspannter Abschluss. Gruene passt als Zwischenstopp ab Austin, Bandera als eigener Ranch-Aufenthalt oder Ausflug. San Antonio ist ein möglicher Rückflugort; Flugzeiten und Preise entscheiden mit.","url":"https://www.visitsanantonio.com/","photo_key":"sanantonio"},{"id":"destination-gruene","kind":"destination","title":"Gruene / New Braunfels","location":"Gruene / New Braunfels","region":"Texas","description":"Historisches Viertel, kleine Läden und Live-Musik in der Gruene Hall. Als halber Tag auf dem Weg zwischen Austin und San Antonio gut geeignet; für einen Konzertabend wäre eine Übernachtung eine Alternative. Konzertprogramm und Tickets für April 2027 noch prüfen.","url":"https://www.gruenetexas.com/","photo_key":"gruene"},{"id":"destination-bandera","kind":"destination","title":"Bandera","location":"Bandera","region":"Texas","description":"Ranch-Aufenthalt, geführter Ausritt oder ein Abend mit Country-Musik. Zwei Nächte würden dem Cowboy-Erlebnis mehr Raum geben. Passt zur 12-Tage-Texas-Variante; bei weniger Zeit als Alternative zu einem Teil des Hill Country einplanen. Ranchpakete und Reitangebote vorab abstimmen.","url":"https://www.banderacowboycapital.com/","photo_key":"bandera"},{"id":"destination-houston","kind":"destination","title":"Houston","location":"Houston","region":"Texas","description":"Space Center Houston als eigener Tagesausflug oder Museen im Museum District. Zwei Nächte wären ein guter Startpunkt für die Planung. Passt zur Route mit New Orleans und Galveston; für die kompakte Dallas–San-Antonio-Reise wäre es ein größerer Zusatzweg.","url":"https://www.visithoustontexas.com/things-to-do/attractions/space-center-houston/","photo_key":"houston"},{"id":"destination-galveston","kind":"destination","title":"Galveston","location":"Galveston","region":"Texas","description":"Am Meer durchatmen, die Seawall entlangspazieren und den historischen Strand District entdecken. Zwei Nächte als Küstenpause vorschlagen. Gut mit Houston kombinierbar; Strandwetter und Baden im April sind nicht garantiert.","url":"https://www.visitgalveston.com/things-to-do/attractions/","photo_key":"galveston"},{"id":"destination-littlerock","kind":"destination","title":"Little Rock","location":"Little Rock","region":"Arkansas","description":"River Market District und ein Spaziergang am Arkansas River. Als Mittagspause zwischen Memphis und Hot Springs oder als Alternative zu einer Nacht in Hot Springs geeignet. Für die 14-Tage-Musikroute eine Option, kein zusätzlicher Pflichtstopp.","url":"https://www.littlerock.com/river-market/","photo_key":"littlerock"},{"id":"destination-neworleans","kind":"destination","title":"New Orleans","location":"New Orleans","region":"Louisiana","description":"French Quarter, Jazz auf der Frenchmen Street und kreolische Küche. Drei Nächte als Auftakt einer eigenen Louisiana–Texas-Route vorschlagen. Nashville und Memphis dabei weglassen, damit die Reise innerhalb von 14 Tagen bleibt. Veranstaltungen und Hotelpreise für Ende April gesondert prüfen.","url":"https://www.neworleans.com/plan/streets/frenchmen-street/","photo_key":"neworleans"},{"id":"hotel-bandera","kind":"hotel","title":"Dixie Dude Ranch","location":"Bandera","region":"Texas","description":"Ranch bei Bandera mit Zimmern und Cabins als Alternative zum Stadthotel. Für zwei Nächte vormerken und Paketleistungen, Reiten, Mindestaufenthalt sowie Zimmer für vier direkt anfragen. Das Kartenfoto zeigt Bandera, nicht die Ranch.","url":"https://dixieduderanch.com/accommodations/","photo_key":"bandera"},{"id":"hotel-houston","kind":"hotel","title":"Magnolia Hotel Houston","location":"Houston","region":"Texas","description":"Historisches Hotel in Downtown als Idee für zwei Nächte in Houston. Der Ausflug zum Space Center benötigt eine eigene Anfahrt. Gesamtpreis für die gewünschte Zimmeraufteilung, Parkkosten und Stornierung vergleichen.","url":"https://www.magnoliahotels.com/houston/","photo_key":"houston"},{"id":"hotel-galveston","kind":"hotel","title":"The Tremont House","location":"Galveston","region":"Texas","description":"Hotel im historischen Downtown von Galveston, passend für Spaziergänge im Strand District. Eine Idee für zwei Nächte an der Küste; die Lage ist in der Altstadt und nicht direkt am Strand. Preise und Parkmöglichkeiten prüfen.","url":"https://www.thetremonthouse.com/","photo_key":"galveston"},{"id":"hotel-neworleans","kind":"hotel","title":"Drury Plaza Hotel New Orleans","location":"New Orleans","region":"Louisiana","description":"An der Poydras Street im Central Business District, mit French Quarter und St.-Charles-Straßenbahn in Reichweite. Für drei Nächte vormerken. Zimmeraufteilung, Parkgebühren und mögliche Zuschläge zum Reisetermin vergleichen.","url":"https://www.druryhotels.com/locations/new-orleans-la/drury-plaza-hotel-new-orleans","photo_key":"neworleans"}]$catalog$::jsonb)
as seed(id text,kind text,title text,location text,region text,description text,url text,photo_key text)
on conflict(id) do update set
 description=excluded.description, url=excluded.url, photo_key=excluded.photo_key, revision=existing.revision+1
where existing.author_key is null and (existing.description,existing.url,existing.photo_key) is distinct from (excluded.description,excluded.url,excluded.photo_key);
commit;
